type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.New(0, 0)
var WsTotal decimal.Decimal = decimal.New(0, 0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var LoanRecVar LoanRec

var loanFileScanner *bufio.Scanner
var loanFile *os.File
var inputDone bool

func formatEdited(value decimal.Decimal, picture string) string {
	// Determine scale = number of 9/Z after '.'
	dotIdx := strings.Index(picture, ".")
	var scale int
	var intPic string
	var fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
		scale = len(fracPic) // assume all 9s
	} else {
		intPic = picture
		fracPic = ""
		scale = 0
	}

	// Truncate toward zero to scale for MOVE (COBOL MOVE truncates, but values already at scale)
	// Ensure value is truncated to scale
	value = value.Truncate(int32(scale))

	negative := value.IsNegative()
	if negative {
		value = value.Neg()
	}

	// Get integer and fractional parts
	// value is positive now
	// Extract integer digits and fractional digits
	var intStr string
	var fracStr string
	if scale > 0 {
		// Shift to integer
		shifted := value.Shift(int32(scale)) // value * 10^scale, truncated
		// shifted should be integer
		s := shifted.StringFixed(0) // no decimal
		// Ensure at least scale+1 digits padding with leading zeros
		if len(s) <= scale {
			s = strings.Repeat("0", scale+1-len(s)) + s
		}
		intStr = s[:len(s)-scale]
		fracStr = s[len(s)-scale:]
	} else {
		intStr = value.StringFixed(0)
		fracStr = ""
	}
	// intStr is decimal integer without leading zeros beyond value (except "0")
	// Remove leading zeros? Keep at least "0"
	// intStr already minimal (no extra leading zeros except zero value)

	// Count placeholder slots in intPic (Z and 9)
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' || ch == 'z' {
			intSlots++
		}
	}
	// If integer digits exceed slots, drop high-order digits
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// Pad intStr on left with zeros to fill intSlots
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}
	// Now intStr length == intSlots, corresponds 1:1 to placeholders left to right

	// Build integer formatted part (including commas)
	// We need to map placeholders to digits
	// Create slice of runes for output of intPic length
	intPicRunes := []rune(intPic)
	// Build digit index pointer
	digitIdx := 0
	// For suppression, need to know if we are still in leading zero suppression zone
	// Z positions are suppressible; 9 positions are not.
	// Suppression continues until we encounter a non-zero digit in a placeholder
	// Once suppression ends, all remaining placeholders print their digits (including zeros)
	// Commas in suppressed zone become spaces.

	// First, create an array of placeholder types aligned with intPic
	// Walk intPic left to right, and for each placeholder consume next digit from intStr
	// For non-placeholder (','), just keep character for now, later may become space if still suppressed

	// Determine suppression end index in terms of placeholder position
	// Find index of last leading zero that should be suppressed
	// Logic: scan placeholders left to right; if digit is '0' and placeholder is Z and all placeholders to the right that are not suppressed still allow? Actually standard: suppress leading zeros where digit is zero and placeholder is Z, until first non-zero digit.
	// Also, if the value is zero, the digit at the last 9 position (units) should be 0, zeros before it suppressed.
	placeHolderDigits := make([]byte, intSlots) // digits char
	for i := 0; i < intSlots; i++ {
		placeHolderDigits[i] = intStr[i]
	}
	// Determine for each placeholder whether it is suppressed
	suppressed := make([]bool, intSlots)
	stillSuppressing := true
	for i := 0; i < intSlots; i++ {
		// Find placeholder type at i (need mapping from placeholder order to pic)
		// Get i-th placeholder type
		// To get type, iterate pic to find i-th placeholder
		// Instead pre-collect types
		_ = i
	}
	// Collect placeholder types in order
	phTypes := []rune{}
	for _, ch := range intPicRunes {
		if ch == 'Z' || ch == '9' || ch == 'z' {
			phTypes = append(phTypes, ch)
		}
	}
	for i := 0; i < intSlots; i++ {
		isZ := phTypes[i] == 'Z' || phTypes[i] == 'z'
		digit := placeHolderDigits[i]
		if stillSuppressing {
			if isZ && digit == '0' {
				// Check if there is any non-zero digit to the right (in any placeholder)
				// If all remaining digits are zero, we still suppress except the last 9 must print
				// Actually if all remaining digits are zero, we want suppression to continue for Z's
				// So we keep suppressed true here; later 9 will not be suppressed
				suppressed[i] = true
			} else {
				// This placeholder is not suppressed, and suppression ends
				suppressed[i] = false
				stillSuppressing = false
			}
		} else {
			suppressed[i] = false
		}
		// However, a '9' placeholder should never be suppressed even if digit is zero and still suppressing?
		// In picture Z,ZZZ,ZZ9.99 the final 9 before dot is '9', so it always prints (0 if value is zero)
		// Our logic above: if isZ is false (i.e., 9) then we set suppressed false and end suppressing, which is correct.
	}

	// Now build output for int part
	var intOut []rune
	phIdx := 0
	for _, ch := range intPicRunes {
		if ch == 'Z' || ch == '9' || ch == 'z' {
			if suppressed[phIdx] {
				intOut = append(intOut, ' ')
			} else {
				intOut = append(intOut, rune(placeHolderDigits[phIdx]))
			}
			phIdx++
		} else if ch == ',' {
			// Comma becomes space if all placeholders to left are suppressed and all placeholders to right up to next? Simplified: if still suppressing at this point (i.e., next placeholder not yet printed), comma is space.
			// Determine if we are still in suppressed zone: if all placeholders before this comma are suppressed and we haven't yet ended suppression, comma is space.
			// Use whether current suppression state at this position is still suppressing
			// phIdx is number of placeholders processed so far; check if all processed placeholders are suppressed and future needs suppression
			if phIdx < intSlots {
				// Look ahead: if next non-suppressed placeholder hasn't occurred, comma is space
				// i.e., if suppressed[phIdx] is true and still suppressing beyond, but our stillSuppressing flag after processing phIdx placeholders indicates
				// Simpler: if all placeholders processed so far are suppressed and the next placeholder is suppressed or we are still suppressing
				allSuppressedSoFar := true
				for k := 0; k < phIdx; k++ {
					if !suppressed[k] {
						allSuppressedSoFar = false
						break
					}
				}
				if allSuppressedSoFar && phIdx < intSlots && suppressed[phIdx] {
					intOut = append(intOut, ' ')
				} else {
					// Check if we are still suppressing before next placeholder: if the next placeholder that will be non-suppressed hasn't appeared yet,
					// comma in leading zero region should be space
					// Use if all remaining placeholders to the left are suppressed -> comma is space
					// Actually standard: comma inside suppressed zone becomes space
					// So if we haven't ended suppression yet (stillSuppressing was true before next digit), comma is space
					// Determine stillSuppressing at this point: are we still in suppression zone before next placeholder?
					// That is true if for all k < phIdx suppressed[k]==true and suppressed[phIdx] is true (next is suppressed) -> comma space
					// Also if phIdx==0 and next is suppressed -> comma shouldn't occur at start normally but handle
					if allSuppressedSoFar {
						// Need to see if suppression continues through next placeholder
						// If next placeholder is suppressed, then comma is in suppressed zone
						intOut = append(intOut, ' ')
					} else {
						intOut = append(intOut, ',')
					}
				}
			} else {
				intOut = append(intOut, ',')
			}
		} else {
			intOut = append(intOut, ch)
		}
	}

	// Build final result
	result := string(intOut)
	if dotIdx >= 0 {
		result += "."
		result += fracStr
	}
	// Ensure length equals picture length (should already)
	// Handle negative (not needed for this program)
	if negative {
		// For simplicity, replace leading space with minus if needed
		// Not required
	}
	return result
}

func formatWsPrinEd(v decimal.Decimal) string {
	return formatEdited(v, "Z,ZZZ,ZZ9.99")
}
func formatWsIntEd(v decimal.Decimal) string {
	return formatEdited(v, "ZZZ,ZZZ,ZZ9.99")
}
func formatWsTotalEd(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZZ,ZZZ,ZZ9.99")
}
func formatWsCount(v int64) string {
	// PIC 9(5) zero-padded to 5
	return fmt.Sprintf("%05d", v)
}

func MAINPARA() {
	OPENLOAN()
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	CLOSELOAN()
	SUMMARYPARA()
}

func OPENLOAN() {
	f, err := os.Open("input.dat")
	if err != nil {
		// If file doesn't exist, treat as empty
		inputDone = false
		loanFileScanner = bufio.NewScanner(strings.NewReader(""))
		return
	}
	loanFile = f
	loanFileScanner = bufio.NewScanner(loanFile)
	// Allow long lines
	loanFileScanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	WsEofFlag = "N"
	inputDone = false
}

func CLOSELOAN() {
	if loanFile != nil {
		loanFile.Close()
	}
}

func READPARA() {
	if loanFileScanner == nil {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	if !loanFileScanner.Scan() {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	line := loanFileScanner.Text()
	// Pad with spaces on right to 21
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	}
	if len(line) > 21 {
		line = line[:21]
	}
	LoanRecVar.LrAcct = line[0:6]
	// LR-PRINCIPAL 9(7)V99 at 6 len 9
	s := line[6 : 6+9]
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	n, _ := decimal.NewFromString(s)
	// implied 2 decimals: divide by 100
	LoanRecVar.LrPrincipal = decimal.New(n.IntPart(), -2)
	// RATE
	s = line[15 : 15+4]
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	n, _ = decimal.NewFromString(s)
	LoanRecVar.LrRate = decimal.New(n.IntPart(), -2)
	// YEARS
	s = line[19 : 19+2]
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	var years int64
	fmt.Sscan(s, &years)
	LoanRecVar.LrYears = years
	WsEofFlag = "N"
	inputDone = false
}

func PROCESSPARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	// Use decimal arithmetic, then round to 2
	prod := LoanRecVar.LrPrincipal.Mul(LoanRecVar.LrRate).Mul(decimal.NewFromInt(LoanRecVar.LrYears))
	// Divide by 100 = shift -2
	val := prod.Shift(-2)
	WsInterest = val.Round(2)
	// Truncate/store to PIC 9(9)V99 => truncate to 2 decimals (already) and low-order digits if overflow (not needed)
	WsInterest = WsInterest.Truncate(2)

	WsTotal = WsTotal.Add(WsInterest).Truncate(2)
	WsCount = WsCount + 1

	WsPrinEd = formatWsPrinEd(LoanRecVar.LrPrincipal)
	WsIntEd = formatWsIntEd(WsInterest)

	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	fmt.Printf("%s %s %s\n", LoanRecVar.LrAcct, WsPrinEd, WsIntEd)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatWsTotalEd(WsTotal)
	fmt.Printf("RECORDS: %s\n", formatWsCount(WsCount))
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	MAINPARA()
}

