func formatWsIntEd(v decimal.Decimal) string {
	return formatEdited(v, "ZZZ,ZZZ,ZZ9.99")
}
func formatWsTotalEd(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZZ,ZZZ,ZZ9.99")
}
func formatWsCount(v int64) string {
	return fmt.Sprintf("%05d", v)
}

// storeNumeric enforces COBOL field size: truncate toward zero to scale,
// then keep only low-order digits that fit in integerDigits+scale digits.
func storeNumeric(v decimal.Decimal, integerDigits int, scale int32) decimal.Decimal {
	v = v.Truncate(scale)
	// keep low-order digits: modulo 10^(integerDigits+scale)
	totalDigits := integerDigits + int(scale)
	// modulus as 10^totalDigits
	mod := decimal.New(1, int32(totalDigits))
	// work with absolute shifted integer
	neg := v.IsNegative()
	shifted := v.Shift(scale) // integer
	if neg {
		shifted = shifted.Neg()
		// For negative, COBOL keeps low-order digits and retains sign if non-zero
		// Use modulus on absolute value
		shifted = shifted.Mod(mod)
		if shifted.IsZero() {
			return decimal.New(0, 0).Truncate(scale)
		}
		shifted = shifted.Neg()
	} else {
		shifted = shifted.Mod(mod)
	}
	return shifted.Shift(-scale).Truncate(scale)
}

func MAINPARA() {
	OPENLOAN()
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	CLOSELOAN()
	SUMMARYPARA()
}

func OPENLOAN() {
	f, err := os.Open("input.dat")
	if err != nil {
		inputDone = false
		loanFileScanner = bufio.NewScanner(strings.NewReader(""))
		return
	}
	loanFile = f
	loanFileScanner = bufio.NewScanner(loanFile)
	loanFileScanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	WsEofFlag = "N"
	inputDone = false
}

func CLOSELOAN() {
	if loanFile != nil {
		loanFile.Close()
	}
}

func READPARA() {
	if loanFileScanner == nil {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	if !loanFileScanner.Scan() {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	line := loanFileScanner.Text()
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	}
	if len(line) > 21 {
		line = line[:21]
	}
	LoanRecVar.LrAcct = line[0:6]
	s := line[6 : 6+9]
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	n, _ := decimal.NewFromString(s)
	LoanRecVar.LrPrincipal = decimal.New(n.IntPart(), -2)
	s = line[15 : 15+4]
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	n, _ = decimal.NewFromString(s)
	LoanRecVar.LrRate = decimal.New(n.IntPart(), -2)
	s = line[19 : 19+2]
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	var years int64
	fmt.Sscan(s, &years)
	LoanRecVar.LrYears = years
	WsEofFlag = "N"
	inputDone = false
}

func PROCESSPARA() {
	prod := LoanRecVar.LrPrincipal.Mul(LoanRecVar.LrRate).Mul(decimal.NewFromInt(LoanRecVar.LrYears))
	val := prod.Shift(-2)
	rounded := val.Round(2)
	WsInterest = storeNumeric(rounded, 9, 2)

	WsTotal = storeNumeric(WsTotal.Add(WsInterest), 11, 2)
	WsCount = WsCount + 1
	if WsCount > 99999 {
		WsCount = WsCount % 100000
	}

	WsPrinEd = formatWsPrinEd(LoanRecVar.LrPrincipal)
	WsIntEd = formatWsIntEd(WsInterest)

	fmt.Printf("%s %s %s\n", LoanRecVar.LrAcct, WsPrinEd, WsIntEd)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatWsTotalEd(WsTotal)
	fmt.Printf("RECORDS: %s\n", formatWsCount(WsCount))
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	MAINPARA()
}
